const md=t=>{const il=x=>esc(x).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\*(.+?)\*/g,'<i>$1</i>').replace(/\[(.+?)\]\((.+?)\)/g,'<a href="$2" rel="nofollow">$1</a>');let h='',inT=0,inL=0;for(const l of t.split('\n')){if(/^\|/.test(l)){if(/^\|[-| ]+\|$/.test(l))continue;const c=l.split('|').slice(1,-1).map(x=>x.trim());h+=(inT?'':'<div class="tw"><table>')+'<tr>'+c.map(x=>(inT?'<td>':'<th scope="col">')+il(x)+(inT?'</td>':'</th>')).join('')+'</tr>';inT=1;continue}if(inT){h+='</table></div>';inT=0}if(/^- /.test(l)){h+=(inL?'':'<ul>')+'<li>'+il(l.slice(2))+'</li>';inL=1;continue}if(inL){h+='</ul>';inL=0}if(/^#{1,3} /.test(l)){const n=Math.min(4,l.match(/^#+/)[0].length+1);h+=`<h${n}>${il(l.replace(/^#+ /,''))}</h${n}>`}else if(/^---/.test(l))h+='<hr style="border:0;border-top:1px solid var(--bd)">';else if(l.trim())h+='<p>'+il(l)+'</p>'}return h+(inT?'</table></div>':'')+(inL?'</ul>':'')};
const C=Object.fromEntries(CATS.map(c=>[c[0],{id:c[0],name:c[1],desc:c[3],vs:V.filter(v=>v.cat===c[0])}]));
const cutL=changes.filter(c=>c.date.startsWith('2026')&&/price increase|removed|sunset/i.test(c.type));const PROOF={cuts:cutL.length,cutNames:cutL.map(c=>c.vendor).join(', ')};
const nVer=V.filter(v=>v.verified).length,nFree=V.filter(v=>v.free==='yes').length;
const SHV=Object.values(SH),SH_FIRST=SHV.map(x=>x.first).filter(Boolean).sort()[0],SH_N=SHV.reduce((a,b)=>a+b.versions,0),SH_GAPS=V.filter(v=>SH[v.id]?.gaps?.length);
const shLine=v=>{const h=SH[v.id];if(!h||!h.versions)return 'No saved snapshot yet';return `${h.versions} saved version${h.versions>1?'s':''} since ${h.first}${h.gaps.length?` (gap: ${h.gaps.length} earlier version overwritten, ${h.gaps[0].date})`:''}`};
// Evidence-based picks (only claims drawn from vendors.json)
const TAKES={apm:['newrelic','New Relic’s perpetual tier lists 100 GB ingest/month plus one full platform user — the largest stated allowance among verified APM vendors. Grafana Cloud is the pick if you want an open stack (10k active series, 14-day retention). Datadog’s free plan caps at 5 hosts with 1-day metric retention, which is fine for evaluation and little else.'],
 logs:['axiom','Axiom’s $0 plan (500 GB/mo loading compute, 25 GB storage, no card) is the most generous verified logging offer. Logz.io, Papertrail, Mezmo and Coralogix are trial or paid only per their pages, so budget accordingly if you pick them.'],
 errors:['sentry','Sentry and Honeybadger both list 5,000 errors/month for one user; Honeybadger adds unlimited projects and 50 MB/day of performance & logs, which edges it for solo devs. Sentry wins on ecosystem. GlitchTip (1,000 events, unlimited projects) is the small Sentry-compatible fallback.'],
 uptime:['uptimerobot','UptimeRobot lists 50 monitors at 5-minute intervals with no card, and since October 2026 its pricing page allows commercial projects on the free plan. Hyperping (20 monitors) and Instatus (15 monitors, 2-min checks) are the runners-up; Healthchecks.io (20 jobs) is the cron-monitoring pick.'],
 incident:['pagerduty','PagerDuty’s free plan covers 5 users with one schedule and escalation policy — enough for a tiny team’s rotation. incident.io’s free plan is the better choice if you live in Slack/Teams and need a status page too. Rootly lists no free tier.'],
 llm:['langfuse','Langfuse Hobby lists 50k units/month with all platform features (limited) and no card — the broadest verified free LLM tier. Helicone Hobby (10,000 requests, 1 GB) is simpler for gateway-style logging. Arize AX Free (25k spans, 1 GB/mo, no card) and Opik Free Cloud (25k spans/mo) are solid runners-up; LangSmith Developer caps you at 1 seat and 5k base traces, and Lunary now requires payment for new workspaces.'],
 product:['posthog','PostHog is the only verified free option here: 1M analytics events and 5K recordings per month, and usage stops at the limits rather than billing you. LogRocket lists a free trial only.']};
